"""Exercise the recurring archive entry point using generated bytes only."""
from contextlib import contextmanager
from pathlib import Path
import sys
import unittest
from unittest.mock import Mock, patch

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from postgres import pp_sealed_archive as archive
from postgres.pp_retirement_report import bound_catalog
from postgres.archive_codec import ArchiveUnavailable
from postgres_lifecycle_fixtures import MemoryRepository, ImmutableMemoryTransport, generated_rows


class SealedFixture(MemoryRepository):
    def __init__(self, count):
        super().__init__()
        self.record.update(origin_id=archive.ORIGIN, seal_count=count)
        self.count = count

    @contextmanager
    def raw_archive_lock(self, origin):
        assert origin == archive.ORIGIN
        yield

    @contextmanager
    def transaction(self):
        connection = Mock()
        connection.execute.return_value.fetchone.return_value = (
            self.record if self.record['state'] == 'sealed' else None)
        yield connection

    def archive_page(self, generation_id, after, limits):
        first = int(after[1].split('-')[1]) + 1 if after else 0
        last = min(self.count, first + limits.max_rows)
        rows = generated_rows(generation_id, last-first, archive.ORIGIN)
        for i, row in enumerate(rows, first):
            row.update(event_id=f'event-{i:08d}', content_hash=f'{i:064x}')
        return rows, last < self.count


class ArchiveTests(unittest.TestCase):
    def test_archive_catalog_is_bound_to_readback_and_exact_object(self):
        repo = SealedFixture(3)
        archive.cycle(repo, ImmutableMemoryTransport())
        g = dict(repo.record, verified_at='sample')
        rows = [dict(m, verified_at='sample', verification={'method':'fresh_authenticated_readback'})
                for m in repo.manifests(g['generation_id'])]
        self.assertTrue(bound_catalog(g, rows))
        for patch_values in ({'object_key':'other/file'}, {'verification':None},
                             {'row_count':1}, {'manifest_id':'raw.events:999999999999'}):
            with self.subTest(patch_values=patch_values):
                self.assertFalse(bound_catalog(g, [dict(rows[0], **patch_values)]))
        self.assertFalse(bound_catalog(dict(g, seal_hash='0'*64), rows))

    def test_sealed_backlog_and_observed_peak_projection(self):
        for count in (4845, 36180):
            with self.subTest(count=count):
                repo, raw = SealedFixture(count), ImmutableMemoryTransport()
                raw.fail_get = True
                with self.assertRaises(ArchiveUnavailable):
                    archive.cycle(repo, raw)
                self.assertEqual((repo.record['state'],repo.record['hold_reason'],repo.catalog),
                                 ('sealed','archive_unavailable',[]))
                raw.fail_get = False
                verified = 0
                while verified < count:
                    result = archive.cycle(repo, raw)
                    self.assertGreater(result['rows'], 0)
                    verified += result['rows']
                self.assertEqual((verified, result['status']), (count, 'archived'))
                self.assertEqual(len(raw.objects), (count+499)//500)
                self.assertEqual(repo.retire_calls, 0)
                self.assertEqual(archive.cycle(repo, raw)['status'], 'idle')

    def test_disabled_before_secret_access(self):
        with patch.object(archive, 'private_dsn') as secret:
            self.assertEqual(archive.main([]), 1)
            secret.assert_not_called()
